SELECT akidata_q.subject_id, (akidata_q.q3 - akidata_q.q1) AS interquartile_range, AVG(akidata.los) AS average_los, SUM(CASE WHEN akidata.deathtime IS NOT NULL THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(akidata.subject_id), 0) AS mortality_rate, (SELECT los FROM admissions WHERE subject_id = akidata_q.subject_id ORDER BY los DESC LIMIT 1) AS last_los FROM akidata JOIN akidata_q ON akidata.subject_id = akidata_q.subject_id GROUP BY akidata_q.subject_id;